def write_url(env):
    """Return the URL the write pool should open against, or None.

    `env` is a mapping like os.environ. DATABASE_WRITE_URL names the write
    role and DATABASE_URL names the read-only role.
    """
    return env.get("DATABASE_WRITE_URL", env.get("DATABASE_URL"))

def write(db, sql):
    """Run one statement with its audit row, as write_database does.

    Returns {"status": "committed" or "failed", "audit_id": int, "rows": int}.
    """
    with db.transaction() as c:
        try:
            tag = c.execute(sql)
            rows = int(tag.split()[-1])
            audit_id = c.insert_audit(sql, True, rows)
            return {"status": "committed", "audit_id": audit_id, "rows": rows}
        except DatabaseError:
            audit_id = c.insert_audit(sql, False, 0)
            return {"status": "failed", "audit_id": audit_id, "rows": 0}

questions.solution:
def write(db, sql):
    """Run one statement with its audit row, as write_database does.

    Returns {"status": "committed" or "failed", "audit_id": int, "rows": int}.
    """
    try:
        with db.transaction() as c:
            tag = c.execute(sql)
            rows = int(tag.split()[-1])
            audit_id = c.insert_audit(sql, True, rows)
    except DatabaseError:
        # The transaction has rolled back; record the failure on a new connection.
        try:
            with db.connection() as fresh:
                audit_id = fresh.insert_audit(sql, False, 0)
        except DatabaseError:
            audit_id = 0  # never lose the original failure behind a second one
        return {"status": "failed", "audit_id": audit_id, "rows": 0}
    return {"status": "committed", "audit_id": audit_id, "rows": rows}

