from contextlib import contextmanager


class DatabaseError(Exception):
    pass


class FakeDB:
    """A tiny stand-in with PostgreSQL's transaction rules.

    A statement or insert that fails inside a transaction aborts it: every
    later call on that connection fails, and leaving the block rolls back.
    """

    def __init__(self, tag="UPDATE 1", fail_sql=False, fail_audit=False):
        self.tag, self.fail_sql, self.fail_audit = tag, fail_sql, fail_audit
        self.applied, self.audit, self.next_id = [], [], 1

    @contextmanager
    def transaction(self):
        c = Conn(self, in_tx=True)
        try:
            yield c
        except BaseException:
            raise
        else:
            if not c.aborted:
                self.applied += c.pending_sql
                self.audit += c.pending_audit

    @contextmanager
    def connection(self):
        yield Conn(self, in_tx=False)


class Conn:
    def __init__(self, db, in_tx):
        self.db, self.in_tx, self.aborted = db, in_tx, False
        self.pending_sql, self.pending_audit = [], []

    def _fail(self, message):
        if self.in_tx:
            self.aborted = True
        raise DatabaseError(message)

    def execute(self, sql):
        if self.aborted:
            raise DatabaseError("current transaction is aborted")
        if self.db.fail_sql:
            self._fail("permission denied for table orders")
        (self.pending_sql if self.in_tx else self.db.applied).append(sql)
        return self.db.tag

    def insert_audit(self, sql, success, rows):
        if self.aborted:
            raise DatabaseError("current transaction is aborted")
        if self.db.fail_audit:
            self._fail("permission denied for table mcp_audit_log")
        row_id = self.db.next_id
        self.db.next_id += 1
        (self.pending_audit if self.in_tx else self.db.audit).append((row_id, sql, success, rows))
        return row_id


SQL = "UPDATE users SET active = FALSE WHERE id = 3"

db = FakeDB()
assert write(db, SQL) == {"status": "committed", "audit_id": 1, "rows": 1}
assert db.applied == [SQL] and db.audit == [(1, SQL, True, 1)]

db = FakeDB(tag="DELETE 2")
assert write(db, "DELETE FROM orders WHERE id < 3")["rows"] == 2, "the count is the tag's last field"
db = FakeDB(tag="INSERT 0 3")
assert write(db, "INSERT INTO users (email) VALUES ('a@x'), ('b@x'), ('c@x')")["rows"] == 3, "an INSERT tag has three fields; the count is the last"

db = FakeDB(fail_sql=True)
result = write(db, SQL)
assert result["status"] == "failed" and result["rows"] == 0
assert db.applied == [], "a failed statement changes nothing"
assert [(s, ok) for _, s, ok, _ in db.audit] == [(SQL, False)], "the failure must be recorded"
assert result["audit_id"] == db.audit[0][0]

db = FakeDB(fail_audit=True)
result = write(db, SQL)
assert db.applied == [], "a change whose audit row failed must roll back with it"
assert result == {"status": "failed", "audit_id": 0, "rows": 0}, "a lost failure row is reported as id 0"
assert db.audit == []
print("all write tests passed")
